use std::env;
use std::io::{self, BufRead, Read, Write};
use std::process;

#[derive(Default)]
struct Config {
    fields: Option<String>,
    bytes: Option<String>,
    characters: Option<String>,
    lines: Option<String>,
    delimiter: Option<String>,
    regex: Option<String>,
    replace_delimiter: Option<String>,
    trim: Option<String>,
    fallback_oob: Option<String>,
    greedy: bool,
    compress: bool,
    only_delimited: bool,
    zero_terminated: bool,
    complement: bool,
    join: Option<bool>,
    json: bool,
    no_mmap: bool,
    fixed_memory: Option<usize>,
    input_file: Option<String>,
}

fn print_help() {
    println!("tuc 1.3.0");
    println!("Cut text (or bytes) where a delimiter matches, then keep the desired parts.");
    println!("");
    println!("USAGE:");
    println!("    tuc [FLAGS] [OPTIONS] < input");
    println!("    tuc [FLAGS] [OPTIONS] filepath");
    // ... I should match the help output more closely if I want to be perfect, but let's focus on functionality first.
}

fn main() {
    let mut config = Config::default();
    let args: Vec<String> = env::args().collect();
    let mut i = 1;
    while i < args.len() {
        match args[i].as_str() {
            "-h" | "--help" => {
                print_help();
                process::exit(0);
            }
            "-V" | "--version" => {
                println!("tuc 1.3.0");
                process::exit(0);
            }
            "-g" | "--greedy-delimiter" => config.greedy = true,
            "-p" | "--compress-delimiter" => config.compress = true,
            "-s" | "--only-delimited" => config.only_delimited = true,
            "-z" | "--zero-terminated" => config.zero_terminated = true,
            "-m" | "--complement" => config.complement = true,
            "-j" | "--join" => config.join = Some(true),
            "--no-join" => config.join = Some(false),
            "--json" => config.json = true,
            "--no-mmap" => config.no_mmap = true,
            "-f" | "--fields" => {
                i += 1;
                if i < args.len() { config.fields = Some(args[i].clone()); }
            }
            "-b" | "--bytes" => {
                i += 1;
                if i < args.len() { config.bytes = Some(args[i].clone()); }
            }
            "-c" | "--characters" => {
                i += 1;
                if i < args.len() { config.characters = Some(args[i].clone()); }
            }
            "-l" | "--lines" => {
                i += 1;
                if i < args.len() { config.lines = Some(args[i].clone()); }
            }
            "-d" | "--delimiter" => {
                i += 1;
                if i < args.len() { config.delimiter = Some(args[i].clone()); }
            }
            "-e" | "--regex" => {
                i += 1;
                if i < args.len() { config.regex = Some(args[i].clone()); }
            }
            "-r" | "--replace-delimiter" => {
                i += 1;
                if i < args.len() { config.replace_delimiter = Some(args[i].clone()); }
            }
            "-t" | "--trim" => {
                i += 1;
                if i < args.len() { config.trim = Some(args[i].clone()); }
            }
            "--fallback-oob" => {
                i += 1;
                if i < args.len() { config.fallback_oob = Some(args[i].clone()); }
            }
            "-M" | "--fixed-memory" => {
                i += 1;
                if i < args.len() { config.fixed_memory = Some(args[i].parse().unwrap()); }
            }
            _ => {
                if args[i].starts_with('-') {
                    // Handle combined flags like -gj
                    let chars: Vec<char> = args[i].chars().skip(1).collect();
                    for c in chars {
                        match c {
                            'g' => config.greedy = true,
                            'p' => config.compress = true,
                            's' => config.only_delimited = true,
                            'z' => config.zero_terminated = true,
                            'm' => config.complement = true,
                            'j' => config.join = Some(true),
                            'V' => { println!("tuc 1.3.0"); process::exit(0); }
                            'h' => { print_help(); process::exit(0); }
                            _ => {
                                eprintln!("tuc: unknown option: -{}", c);
                                process::exit(1);
                            }
                        }
                    }
                } else {
                    if config.input_file.is_none() {
                        config.input_file = Some(args[i].clone());
                    } else {
                        eprintln!("tuc: unexpected arguments: {:?}", &args[i..]);
                        process::exit(1);
                    }
                }
            }
        }
        i += 1;
    }

    // Default join behavior
    if config.replace_delimiter.is_some() {
        if config.join.is_none() { config.join = Some(true); }
    }
    if config.lines.is_some() {
        if config.join.is_none() { config.join = Some(true); }
    }

    // Default delimiter
    if config.delimiter.is_none() && config.regex.is_none() {
        config.delimiter = Some("\t".to_string());
    }
}
EOF
"}

