fn split_line(line: &str, delimiter: &str, greedy: bool) -> (Vec<String>, Vec<String>) {
    let mut fields = Vec::new();
    let mut delims = Vec::new();

    if delimiter.is_empty() {
        // Should not happen with -d, but maybe with empty regex?
        fields.push(line.to_string());
        return (fields, delims);
    }

    let mut last_pos = 0;
    let mut current_pos = 0;

    while let Some(pos) = line[current_pos..].find(delimiter).map(|p| p + current_pos) {
        if greedy {
            // Find the end of the consecutive delimiters
            let mut end_pos = pos + delimiter.len();
            while line[end_pos..].starts_with(delimiter) {
