        for m in matches:
            fields.append(text[last:m.start()])
            seps.append(m.group())
            last = m.end()
        fields.append(text[last:])
        return fields, seps

def apply_trim(text, delim, trim_type):
    if not delim or not trim_type:
        return text
    t = trim_type.lower()
    if t in ('l', 'left', 'both', 'b'):
        while text.startswith(delim):
            text = text[len(delim):]
    if t in ('r', 'right', 'both', 'b'):
        while text.endswith(delim):
            text = text[:-len(delim)]
    return text

def parse_bounds(s):
    if not s: return []
    if '{' in s and '}' in s: # Check for format string
        return [{'format_string': s}]

    res = []
    for part in s.split(','):
        if not part:
            print(f"failed to parse '{s}': Field format error: empty field", file=sys.stderr)
            sys.exit(1)
        fallback = None
        if '=' in part:
            main, fallback = part.split('=', 1)
        else:
            main = part
        if ':' in main:
            colons = main.split(':')
            start = int(colons[0]) if colons[0] else None
            end = int(colons[1]) if colons[1] else None
            res.append({'start': start, 'end': end, 'fallback': fallback, 'is_range': True})
        else:
            try:
                val = int(main)
                if val == 0:
                    print(f"failed to parse '0': Zero is not a valid field", file=sys.stderr)
                    sys.exit(1)
                res.append({'start': val, 'fallback': fallback, 'is_range': False})
            except ValueError:
