                    sys.exit(1)
    return res

def get_field(fields, seps, idx, fallback, oob_fallback):
    n = len(fields)
    actual_idx = resolve_index(idx, n)
    if actual_idx is not None and 0 <= actual_idx < n:
        return fields[actual_idx]
    if fallback is not None:
        return fallback
    if oob_fallback is not None:
        return oob_fallback
    print(f"Error: Out of bounds: {idx}", file=sys.stderr)
    sys.exit(1)

def get_range(fields, seps, start, end, fallback, oob_fallback, compress, delim):
    n = len(fields)
    s = resolve_index(start, n) if start is not None else 0
    e = resolve_index(end, n) if end is not None else n - 1

    if s is None or e is None or s < 0 or s >= n or e < 0 or e >= n:
        if fallback is not None: return fallback
        if oob_fallback is not None: return oob_fallback
