    return "".join(res)

def process_item(item, fields, seps, config, n):
    if 'format_string' in item:
        # Format string is handled at a higher level
        return None

    if config['complement']:
        # Complement logic: all fields except those in item
        excluded = set()
        if item['is_range']:
            s = resolve_index(item['start'], n) if item['start'] is not None else 0
            e = resolve_index(item['end'], n) if item['end'] is not None else n - 1
            if s is not None and e is not None:
                for i in range(s, e + 1): excluded.add(i)
        else:
            idx = resolve_index(item['start'], n)
            if idx is not None: excluded.add(idx)

        res_fields = []
        for i in range(n):
            if i not in excluded:
                res_fields.append(fields[i])

