        print(f"failed to parse '{start}:{end}': Field left value cannot be greater than right value", file=sys.stderr); sys.exit(1)
    res = []
    for i in range(s_idx, e_idx + 1):
        res.append(fields[i])
        if i < e_idx: res.append(delim if compress else seps[i])
    return "".join(res)

def format_line(fmt, fields, seps, config):
    n = len(fields); res, i = [], 0
    while i < len(fmt):
        if fmt[i:i+2] == '{{': res.append('{'); i += 2
        elif fmt[i:i+2] == '}}': res.append('}'); i += 2
        elif fmt[i] == '{':
            j = fmt.find('}', i)
            if j == -1: res.append(fmt[i:]); break
            bound_str = fmt[i+1:j]; b = parse_bounds(bound_str, config)[0]
            if b.get('is_range'):
                part = get_range(fields, seps, b['start'], b['end'], b['fallback'], config['fallback_oob'], config['compress'], config['delimiter'])
                if part is None: sys.exit(1)
                res.append(part)
            else:
                part = get_field(fields, seps, b['start'], b['fallback'], config['fallback_oob'])
                if part is None: sys.exit(1)
                res.append(part)
            i = j + 1
        else: res.append(fmt[i]); i += 1
    return "".join(res)

def main():
    args = sys.argv[1:]
    config = {'fields': '1:', 'bytes': None, 'characters': None, 'lines': None, 'delimiter': '\t', 'regex': None, 'replace_delimiter': None, 'trim': None, 'fallback_oob': None, 'greedy': False, 'compress': False, 'only_delimited': False, 'zero_terminated': False, 'complement': False, 'join': None, 'json': False, 'input_file': None}
    i = 0
    while i < len(args):
        arg = args[i]
        if arg in ('-f', '--fields'): i += 1; config['fields'] = args[i]
        elif arg in ('-b', '--bytes'): i += 1; config['bytes'] = args[i]; config['fields'] = None
        elif arg in ('-c', '--characters'): i += 1; config['characters'] = args[i]; config['fields'] = None
        elif arg in ('-l', '--lines'): i += 1; config['lines'] = args[i]; config['fields'] = None
        elif arg in ('-d', '--delimiter'): i += 1; config['delimiter'] = args[i]
        elif arg in ('-e', '--regex'): i += 1; config['regex'] = args[i]
        elif arg in ('-r', '--replace-delimiter'): i += 1; config['replace_delimiter'] = args[i]
        elif arg in ('-t', '--trim'): i += 1; config['trim'] = args[i]
        elif arg == '--fallback-oob': i += 1; config['fallback_oob'] = args[i]
        elif arg in ('-g', '--greedy-delimiter'): config['greedy'] = True
        elif arg in ('-p', '--compress-delimiter'): config['compress'] = True
        elif arg in ('-s', '--only-delimited'): config['only_delimited'] = True
        elif arg in ('-z', '--zero-terminated'): config['zero_terminated'] = True
        elif arg in ('-m', '--complement'): config['complement'] = True
        elif arg in ('-j', '--join'): config['join'] = True
        elif arg == '--no-join': config['join'] = False
        elif arg == '--json': config['json'] = True
        elif arg in ('-h', '--help'): sys.exit(0)
        elif arg in ('-V', '--version'): print("tuc 1.3.0"); sys.exit(0)
        elif arg.startswith('-') and len(arg) > 1:
            for char in arg[1:]:
                if char == 'g': config['greedy'] = True
                elif char == 'p': config['compress'] = True
                elif char == 's': config['only_delimited'] = True
                elif char == 'z': config['zero_terminated'] = True
                elif char == 'm': config['complement'] = True
                elif char == 'j': config['join'] = True
        else: config['input_file'] = arg
        i += 1
    if config['lines'] and config['join'] is None: config['join'] = True
    if config['replace_delimiter'] is not None and config['join'] is None: config['join'] = True
    spec = config['bytes'] or config['characters'] or config['lines'] or config['fields']
    bounds = parse_bounds(spec, config)
    f = open(config['input_file'], 'rb') if config['input_file'] else sys.stdin.buffer
    ld = '\0' if config['zero_terminated'] else '\n'
    if config['lines']:
        content = f.read().decode('utf-8', errors='replace')
        lines = content.split(ld)
        if content.endswith(ld): lines.pop()
        n = len(lines)
        results = []
        for b in bounds:
            if config['complement']:
                excluded = set()
                if b['is_range']:
                    s, e = resolve_index(b['start'], n) if b['start'] is not None else 0, resolve_index(b['end'], n) if b['end'] is not None else n-1
                    if s is not None and e is not None:
                        for k in range(s, e+1): excluded.add(k)
                else:
                    idx = resolve_index(b['start'], n)
                    if idx is not None: excluded.add(idx)
                for k in range(n):
                    if k not in excluded: results.append(lines[k])
            elif b['is_range']:
                s, e = resolve_index(b['start'], n) if b['start'] is not None else 0, resolve_index(b['end'], n) if b['end'] is not None else n-1
                if s is not None and e is not None:
                    for k in range(s, e+1): results.append(lines[k])
            else:
                part = get_field(lines, ["\n"]*(n-1), b['start'], b['fallback'], config['fallback_oob'])
                if part is None:
                    sys.stdout.write(ld.join(results) + (ld if config['join'] and results else ""))
                    sys.exit(1)
                results.append(part)
        sep = ld if config['join'] else ""
        sys.stdout.write(sep.join(results) + (ld if config['join'] and results else ""))
        return
    for line_bytes in f:
        line = line_bytes.decode('utf-8', errors='replace')
        had_newline = line.endswith(ld)
        if had_newline: line = line[:-len(ld)]
        if config['trim']:
            if config['trim'].lower() in ('l', 'left', 'b', 'both'):
                while line.startswith(config['delimiter']): line = line[len(config['delimiter']):]
            if config['trim'].lower() in ('r', 'right', 'b', 'both'):
                while line.endswith(config['delimiter']): line = line[:-len(config['delimiter'])]
        if config['compress'] and not config['characters'] and not config['bytes']:
            line = re.sub(re.escape(config['delimiter']) + '+', config['delimiter'], line)
        if config['only_delimited'] and config['delimiter'] not in line: continue
        if config['bytes']:
            line_b = line.encode('utf-8', errors='replace')
            fields = [line_b[k:k+1].decode('utf-8', errors='replace') for k in range(len(line_b))]
            seps = [""] * (len(fields)-1)
        elif config['characters']:
            fields = list(line); seps = [""] * (len(fields)-1)
        elif config['regex']:
            fields, seps = split_with_regex(line, config['regex'], config['greedy'])
        else:
            fields, seps = split_with_sep(line, config['delimiter'], config['greedy'])
        n = len(fields)
        if bounds and 'format_string' in bounds[0]:
            sys.stdout.write(format_line(bounds[0]['format_string'], fields, seps, config) + (ld if had_newline else ""))
            continue
        line_results = []
        for b in bounds:
            if config['complement']:
                excluded = set()
                if b['is_range']:
                    s, e = resolve_index(b['start'], n) if b['start'] is not None else 0, resolve_index(b['end'], n) if b['end'] is not None else n-1
                    if s is not None and e is not None:
                        for k in range(s, e+1): excluded.add(k)
                else:
                    idx = resolve_index(b['start'], n)
                    if idx is not None: excluded.add(idx)
                for k in range(n):
                    if k not in excluded: line_results.append(fields[k])
            elif b['is_range']:
                part = get_range(fields, seps, b['start'], b['end'], b['fallback'], config['fallback_oob'], config['compress'], config['delimiter'])
                if part is None:
                    sep = config['replace_delimiter'] if config['replace_delimiter'] is not None else (config['delimiter'] if config['join'] else "")
                    sys.stdout.write(sep.join(line_results))
                    sys.exit(1)
                line_results.append(part)
            else:
                part = get_field(fields, seps, b['start'], b['fallback'], config['fallback_oob'])
                if part is None:
                    sep = config['replace_delimiter'] if config['replace_delimiter'] is not None else (config['delimiter'] if config['join'] else "")
                    sys.stdout.write(sep.join(line_results))
                    sys.exit(1)
                line_results.append(part)
        if config['json']:
            json_results = []
            for b in bounds:
                if b['is_range']:
                    s, e = resolve_index(b['start'], n) if b['start'] is not None else 0, resolve_index(b['end'], n) if b['end'] is not None else n-1
                    if s is not None and e is not None:
                        for k in range(s, e+1): json_results.append(fields[k])
                else: json_results.append(get_field(fields, seps, b['start'], b['fallback'], config['fallback_oob']))
            sys.stdout.write(json.dumps(json_results, separators=(',', ':')) + (ld if had_newline else ""))
        else:
            sep = config['replace_delimiter'] if config['replace_delimiter'] is not None else (config['delimiter'] if config['join'] else "")
            sys.stdout.write(sep.join(line_results) + (ld if had_newline else ""))
if __name__ == "__main__": main()
